const json = pm.response.json();

if (json && json.apiKey) {
    if (pm.environment.name) {
        pm.environment.set("apiKey", json.apiKey);
        console.log("apiKey salva no environment '" + pm.environment.name + "'.");
    } else {
        pm.collectionVariables.set("apiKey", json.apiKey);
        console.log("Nenhum environment selecionado: apiKey salva como variavel da collection.");
    }
}
